import{t as e}from"./utils-COoNfFoj.js";var t={slug:`jahnavi-shah-learnloop`,influencerName:`Jahnavi Shah`,influencerHandle:`@jahnshah`,influencerAvatarUrl:`${e}/jahnavi-shah-learnloop-avatar.jpg`,heroDescription:`To keep up with all the updates happening in the AI world, but also have accountability with friends and gamify it by adding a leaderboard.`,assetTitle:`LearnLoop`,screenshotUrl:`${e}/jahnavi-shah-learnloop.png`,remixUrl:`https://www.perplexity.ai/computer/a/learnloop-preview-VVh4mLnATISIJKSFBT1UUA`,promptTitle:`Try Jahnavi's Prompt`,promptText:`You are an expert AI product manager and full-stack engineer helping build a social AI learning accountability app for small private friend groups. The goal is to keep users updated on AI trends while creating accountability through a leaderboard. Research the best AI news/learning sources, design an MVP and V1, propose a technical architecture, and generate starter code and schemas. Product goals: automatically curate weekly AI updates, allow users to quickly mark what they learned, create a social accountability loop, and keep interactions low-friction and tap-based. Research top AI sources including newsletters, blogs, Reddit communities, and Twitter/X creators, and provide type, access method (RSS/API/scraping), and reliability in a table. Design an MVP with a weekly AI digest (5–10 items), actions (Read/Learned/Saved + notes up to 200 characters), leaderboard (+1 read, +2 note, +3 shared resource with weekly reset), private groups, and an activity feed. Output a feature breakdown, user flow, and database schema. Expand V1 with personalized feeds, AI summaries, enhanced notes, streaks, notifications, and resource upvotes, and explain MVP → V1 changes plus AI workflows. Recommend a stack using React/Next.js, Supabase/Firebase, OpenAI API, and RSS + cron jobs, including system design, APIs, and digest flow. Generate implementation details for schemas (Users, Groups, Resources, Activity, Leaderboard), backend logic, frontend pages, and sample code for AI news fetching, summaries, and leaderboard calculations. Also create production-ready prompts for summarization, note enhancement, and feed personalization. Structure the output as: Research, MVP Spec, V1 Spec, Architecture, Code, Prompts. Keep everything practical and ready to build.`};export{t as default};
